mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, time, urllib.request, urllib.error, sys
BASE = "http://localhost:8080"
tok = None
log = []
def get_token():
    global tok
    while True:
        try:
            req = urllib.request.Request(BASE + "/token", method="POST", data=b"")
            with urllib.request.urlopen(req, timeout=30) as r:
                tok = json.load(r)["token"]; return
        except urllib.error.HTTPError as e:
            handle(e)
        except Exception as e:
            log.append(("token-exc", repr(e))); time.sleep(1)
def handle(e):
    ra = e.headers.get("Retry-After")
    body = e.read()[:300]
    log.append((e.code, ra, body.decode(errors="replace")))
    if e.code == 429:
        time.sleep(float(ra) if ra else 1)
    elif e.code == 401:
        get_token()
    else:
        time.sleep(float(ra) if ra else 0.5)
def get(path, allow404=False):
    if tok is None: get_token()
    while True:
        try:
            req = urllib.request.Request(BASE + path, headers={"Authorization": f"Bearer {tok}"})
            with urllib.request.urlopen(req, timeout=30) as r:
                raw = r.read()
            try:
                return json.loads(raw)
            except ValueError:
                log.append(("badjson", path, raw[:200].decode(errors="replace"))); time.sleep(0.5)
        except urllib.error.HTTPError as e:
            if e.code == 404 and allow404:
                log.append((404, path)); return None
            handle(e)
        except Exception as e:
            log.append(("exc", path, repr(e))); time.sleep(1)
pages = {}
path = "/orders?page=1"
while path:
    d = get(path)
    if not isinstance(d, dict) or "items" not in d:
        log.append(("weird", path, str(d)[:200])); time.sleep(0.5); continue
    pages[d["page"]] = d
    path = d["next"]
tp = {d["total_pages"] for d in pages.values()}
print("pages", sorted(pages), "total_pages", tp)
for p in range(1, max(tp)+1):
    if p not in pages:
        pages[p] = get(f"/orders?page={p}")
cids = sorted({o["customer_id"] for d in pages.values() for o in d["items"]})
custs = {c: get(f"/customers/{c}", allow404=True) for c in cids}
json.dump({"pages": pages, "customers": custs}, open("/tmp/recon/raw.json", "w"))
print("customers", len(custs))
from collections import Counter
print(Counter(str(x[0]) for x in log))
for x in log[:40]: print(x)
EOF
python3 -I /tmp/recon/fetch.py

